<script lang="ts">
  import { Browser } from '@wailsio/runtime';
  import type { SidebarItem } from '../../bindings/arclights/networks/index';
  import {
    siBilibili,
    siDiscord,
    siFacebook,
    siInstagram,
    siLine,
    siNaver,
    siReddit,
    siSinaweibo,
    siTelegram,
    siTiktok,
    siTwitch,
    siVk,
    siWechat,
    siX,
    siYoutube
  } from 'simple-icons';

  type Label = NonNullable<SidebarItem['sidebar_labels']>[number];

  let { sidebar = [] }: { sidebar?: SidebarItem[] | null } = $props();

  const brandIcons: Record<string, { path: string }> = {
    x: siX,
    twitter: siX,
    tiktok: siTiktok,
    douyin: siTiktok,
    facebook: siFacebook,
    youtube: siYoutube,
    instagram: siInstagram,
    discord: siDiscord,
    reddit: siReddit,
    telegram: siTelegram,
    vk: siVk,
    bilibili: siBilibili,
    wechat: siWechat,
    weibo: siSinaweibo,
    sinaweibo: siSinaweibo,
    twitch: siTwitch,
    line: siLine,
    naver: siNaver,
    naver_cafe: siNaver,
    naver_game: siNaver
  };

  const key = (media: string): string => media?.trim().toLowerCase() ?? '';
  const brandPath = (media: string): string => brandIcons[key(media)]?.path ?? '';

  const labelsOf = (item: SidebarItem): Label[] => item.sidebar_labels ?? [];
  const isPopup = (item: SidebarItem) =>
    item.display_type === 'DisplayType_LIST' || item.display_type === 'DisplayType_GRID';
  const isGrid = (item: SidebarItem) => item.display_type === 'DisplayType_GRID';

  const open = (url: string) => {
    if (url) Browser.OpenURL(url);
  };
</script>

