<nav class="socials" data-no-drag aria-label="Social links">
  {#each sidebar ?? [] as item, i (item.media + i)}
    {#if isPopup(item)}
      <div class="item">
        <button class="btn has-popup" aria-label={item.media} onclick={() => open(item.jump_url)}>
          {@render icon(item)}
        </button>

        <div class="popup" class:has-qr={!!item.pic?.url}>
          {#if isGrid(item)}
            <div class="panel w-grid">
              <div class="grid">
                {#each labelsOf(item) as l, j (j)}
                  <button class="tool" onclick={() => open(l.jump_url)}>
                    {#if l.pic_url}<img src={l.pic_url} alt="" />{/if}
                    <span>{l.content}</span>
                  </button>
                {/each}
              </div>
            </div>
          {:else}
            <div class="panel" class:w-qr={!!item.pic?.url} class:w-list={!item.pic?.url}>
              {#if item.pic?.url}
                <div class="qr">
                  <img src={item.pic.url} alt={item.pic.description ?? ''} />
                  {#if item.pic.description}<span class="qr-caption">{item.pic.description}</span>{/if}
                </div>
              {/if}
              {#each labelsOf(item) as l, j (j)}
                <button class="row" onclick={() => open(l.jump_url)}>
                  <span>{l.content}</span>
                  {@render chevron()}
                </button>
              {/each}
            </div>
          {/if}
        </div>
      </div>
    {:else}
      <button class="btn" aria-label={item.media} onclick={() => open(item.jump_url)}>
        {@render icon(item)}
      </button>
    {/if}
  {/each}
</nav>
